template <typename T, typename Char>
struct range_formatter<
    T, Char,
    enable_if_t<conjunction<std::is_same<T, remove_cvref_t<T>>,
                            is_formattable<T, Char>>::value>> {
 private:
  detail::range_formatter_type<Char, T> underlying_;
  basic_string_view<Char> separator_ = detail::string_literal<Char, ',', ' '>{};
  basic_string_view<Char> opening_bracket_ =
      detail::string_literal<Char, '['>{};
  basic_string_view<Char> closing_bracket_ =
      detail::string_literal<Char, ']'>{};
  bool is_string_format_ = false;
  bool is_debug_string_format_ = false;

 public:
  FMT_CONSTEXPR range_formatter() {}

  FMT_CONSTEXPR auto underlying() -> detail::range_formatter_type<Char, T>& {
    return underlying_;
  }

  FMT_CONSTEXPR void set_separator(basic_string_view<Char> sep) {
    separator_ = sep;
  }

  FMT_CONSTEXPR void set_brackets(basic_string_view<Char> open,
                                  basic_string_view<Char> close) {
    opening_bracket_ = open;
    closing_bracket_ = close;
  }

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    auto it = ctx.begin();
    auto end = ctx.end();

    if (it != end && *it == 'n') {
      set_brackets({}, {});
      ++it;
    }

    if constexpr (is_char<T>::value) {
      if (it != end && *it == '?') {
        is_debug_string_format_ = true;
        ++it;
      }
      if (it != end && *it == 's') {
        is_string_format_ = true;
        set_brackets(detail::string_literal<Char, '"'>{},
                     detail::string_literal<Char, '"'>{});
        set_separator({});
        ++it;
      }
      if (is_debug_string_format_ && !is_string_format_)
        report_error("invalid format specifier");
    }

    if (it != end && *it != '}') {
      if (*it != ':') report_error("invalid format specifier");
      ++it;
    } else if (!is_string_format_) {
      detail::maybe_set_debug_format(underlying_, true);
    }

    ctx.advance_to(it);
    return underlying_.parse(ctx);
  }

  template <typename R, typename FormatContext>
  auto format(R&& range, FormatContext& ctx) const -> decltype(ctx.out()) {
    detail::range_mapper<buffered_context<Char>> mapper;
    auto out = ctx.out();
    if constexpr (is_char<T>::value) {
      if (is_string_format_) {
        out = detail::copy<Char>(opening_bracket_, out);
        auto it = detail::range_begin(range);
        auto end = detail::range_end(range);
        for (; it != end; ++it) {
          auto&& item = *it;
          if (is_debug_string_format_) {
            out = detail::write_escaped_char_content<Char>(
                out, static_cast<uint32_t>(mapper.map(item)));
          } else {
            ctx.advance_to(out);
            out = underlying_.format(mapper.map(item), ctx);
          }
        }
        out = detail::copy<Char>(closing_bracket_, out);
        return out;
      }
    }
    out = detail::copy<Char>(opening_bracket_, out);
    int i = 0;
    auto it = detail::range_begin(range);
    auto end = detail::range_end(range);
    for (; it != end; ++it) {
      if (i > 0) out = detail::copy<Char>(separator_, out);
      ctx.advance_to(out);
      auto&& item = *it;
      out = underlying_.format(mapper.map(item), ctx);
      ++i;
    }
    out = detail::copy<Char>(closing_bracket_, out);
    return out;
  }
};

